// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, uint256 advance) public {
        vm.assume(actor != address(0));

        advance = bound(advance, 1, 256);

        vm.deal(actor, 2 ether);

        bytes32 guess = keccak256(abi.encodePacked(actor, advance));

        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        for (uint256 i = 0; i < advance; ++i) {
            vm.roll(block.number + 1);
        }

        vm.prank(actor);
        bool firstSettled = true;
        try c.settle() {
            firstSettled = true;
        } catch {
            return;
        }

        vm.prank(actor);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
